import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useWebSocket } from '../context/WebSocketContext';

function Cart({ cart = {}, setOrder, merchantName, merchantEmail, specialInstruction, promotions }) {
    const navigate = useNavigate();
    const socket = useWebSocket();
    const [orderNum, setOrderNum] = useState('');
    const [otp, setOtp] = useState('');
    const [orderDetails, setOrderDetails] = useState(null);
    const [finalOrder, setFinalOrder] = useState(null); // Declare finalOrder here
    const [isProcessing, setIsProcessing] = useState(false);
    const [orderStatus, setOrderStatus] = useState('');

    const cartItems = Array.isArray(cart) ? cart : Object.values(cart);

    const calculateTotal = () => {
        return cartItems.reduce((total, product) => {
            const promotion = promotions.find(p => p.name === product.name);
            const discount = promotion ? promotion.discount / 100 : 0; // Calculate discount
            const discountedPrice = product.price * (1 - discount); // Calculate discounted price

            return total + discountedPrice * product.quantity; // Add discounted price multiplied by quantity to total
        }, 0);
    };

    useEffect(() => {
        if (socket) {
            socket.onmessage = (event) => {
                console.log("Message received from server:", event.data);
                const data = event.data.split(",");
                const action = data[0];

                // Handle different actions from the WebSocket
                if (action === "orderDetails") {
                    setOrderNum(data[4]);
                    setOtp(data[5]);
                    setOrderStatus('Order details received!');

                    if (finalOrder) {
                        navigate('/client-home/orders', { state: finalOrder });
                    }
                } else if (action === "accepted") {
                    setOrderStatus('Your order has been accepted!');
                } else if (action === "ready") {
                    setOrderStatus('Your order is ready. Please head to the counter to collect it.');
                } else if (action === "collected") {
                    setOrderStatus('Your order has been collected! Thank you for your purchase.');
                }
            };
        }
    }, [socket, navigate, finalOrder]); // Include finalOrder in the dependencies

    const handlePlaceOrder = () => {
        const orderDetails = cartItems.map((item) => {
            const promotion = promotions.find(p => p.name === item.name);
            const discount = promotion ? promotion.discount / 100 : 0;
            const discountedPrice = item.price * (1 - discount);

            return {
                name: item.name,
                quantity: item.quantity,
                price: discountedPrice, // Use discounted price
                total: discountedPrice * item.quantity, // Calculate total for this item based on discounted price
                orderInstruction: specialInstruction[item.name] || ''
            };
        });

        const total = orderDetails.reduce((sum, item) => sum + item.total, 0);

        const order = {
            orderDetails,
            orderNum,
            otp,
            total,
            merchantName,
        };

        setOrder(order);
        setFinalOrder(order); // Set finalOrder state here

        // Send order via WebSocket
        const orderDetailsString = cartItems.map(item => item.name).join('/');
        const quantitiesString = cartItems.map(item => item.quantity).join('/');
        if (socket && socket.readyState === WebSocket.OPEN) {
            setIsProcessing(true);
            const stringPacket = `order,${merchantEmail},${orderDetailsString},${quantitiesString},${specialInstruction}`;
            socket.send(stringPacket);
        }
    };

    return (
        <div className="p-6 bg-white shadow-md rounded-lg">
            <h2 className="text-2xl font-bold mb-4">Your Cart</h2>
            {cartItems.length === 0 ? (
                <p>Your cart is empty. Please add some products.</p>
            ) : (
                <div>
                    <div className="grid grid-cols-1 gap-4">
                        {cartItems.map((productDetails, index) => {
                            const promotion = promotions.find(p => p.name === productDetails.name);
                            const discount = promotion ? promotion.discount / 100 : 0; // Calculate discount
                            const originalPrice = productDetails.price;
                            const discountedPrice = originalPrice * (1 - discount); // Apply discount

                            return (
                                <div key={index} className="bg-gray-50 border border-gray-200 rounded-lg p-4 shadow-lg">
                                    <h3 className="text-xl font-semibold mb-2">{productDetails.name}</h3>
                                    <p>Quantity: {productDetails.quantity}</p>

                                    {discount > 0 ? (
                                        <>
                                            <p>
                                                Price per unit: <span className="line-through">R {originalPrice}</span> <span className="text-green-500">R {discountedPrice.toFixed(2)}</span>
                                            </p>
                                            <p>Total: <span className="line-through">R {originalPrice * productDetails.quantity}</span> <span className="text-green-500">R {discountedPrice * productDetails.quantity}</span></p>
                                        </>
                                    ) : (
                                        <>
                                            <p>Price per unit: R {productDetails.price}</p>
                                            <p>Total: R {productDetails.price * productDetails.quantity}</p>
                                        </>
                                    )}

                                    {/* Display the special instruction for each product */}
                                    {specialInstruction[productDetails.name] && (
                                        <p>Special Instruction: {specialInstruction[productDetails.name]}</p>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                    <div className="mt-6">
                        <h3 className="text-xl font-bold">Total Price: R {calculateTotal().toFixed(2)}</h3>
                    </div>
                    <div className="mt-6">
                        <button
                            onClick={handlePlaceOrder}
                            className="px-4 py-2 bg-green-500 text-white font-semibold rounded-md hover:bg-green-600"
                            disabled={isProcessing}
                        >
                            {isProcessing ? 'Processing...' : 'Place Order'}
                        </button>
                        <button
                            onClick={() => {
                                console.log("cart items:" + cartItems);
                                navigate(`/client-home/products/${merchantName}`, {
                                    state: {
                                        drinks: cartItems, // Pass the selected items
                                        specialInstructions: specialInstruction // Pass the special instructions
                                    }
                                });
                            }}
                            className="ml-0 sm:ml-4 px-4  py-2 bg-gray-500 text-white font-semibold rounded-md hover:bg-gray-600"
                            disabled={isProcessing}
                        >
                            Continue Shopping
                        </button>

                    </div>
                </div>
            )}

            {orderStatus && (
                <div className="mt-6 text-center">
                    <p className="text-xl font-semibold text-green-600">{orderStatus}</p>
                </div>
            )}
        </div>
    );
}

export default Cart;