import React, { useState, useEffect } from 'react';
import { useParams, useLocation, useNavigate } from 'react-router-dom';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faSearch } from '@fortawesome/free-solid-svg-icons';
import drinkPic from '../assets/drinkPic.jpg'; // Placeholder for drink image
import storePic from '../assets/merchant-placeholder.jpg'; // Placeholder for store banner image

// Hardcoded list of promotions with percentage discounts
const promotions = [
  { name: 'Mai Tai', discount: 20 }, // 20% discount
  { name: 'Aperol Spritz', discount: 10 }, // 10% discount
  // Add more promotions as needed
];

function Products({ setCart, setSpecialInst, setPromotions }) {
  const { store } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const drinks = location.state?.drinks || []; // Get drinks from location state
  const specialInstructionsFromCart = location.state?.specialInstructions || {}; // Get special instructions from location state
  const [selectedProducts, setSelectedProducts] = useState([]);
  const [filteredDrinks, setFilteredDrinks] = useState(drinks);
  const [showInstructions, setShowInstructions] = useState({});
  const [specialInstructions, setSpecialInstructions] = useState(specialInstructionsFromCart); // Initialize with passed special instructions
  const [drinkSearchTerm, setDrinkSearchTerm] = useState('');

  useEffect(() => {
    setPromotions(promotions);
    console.log(promotions);
  }, [setPromotions]); // Only depend on setPromotions

  useEffect(() => {
    // Filter drinks based on search term
    const filtered = drinks.filter(drink =>
        drink.name.toLowerCase().includes(drinkSearchTerm.toLowerCase())
    );
    setFilteredDrinks(filtered);
  }, [drinkSearchTerm, drinks]); // Update filtered drinks when search term or drinks change

  // Helper function to apply promotions
  const applyPromotion = (drinkName, price) => {
    const promo = promotions.find((p) => p.name === drinkName);
    if (promo) {
      const discountedPrice = price - (price * (promo.discount / 100));
      return discountedPrice.toFixed(2); // Format to 2 decimal places
    }
    return price;
  };

  // Split drinks into promoted and non-promoted
  const promotedDrinks = filteredDrinks.filter((drink) =>
      promotions.some((promo) => promo.name === drink.name)
  );

  const regularDrinks = filteredDrinks.filter((drink) =>
      !promotions.some((promo) => promo.name === drink.name)
  );

  const handleQuantityChange = (productName, price, e) => {
    const value = e.target.value;
    setSelectedProducts((prev) => {
      const filtered = prev.filter((p) => !(p.name === productName));
      if (value > 0) {
        return [
          ...filtered,
          {
            name: productName,
            price,
            quantity: value,
            specialInstruction: specialInstructions[productName] || '', // Ensure this line is present
          },
        ];
      }
      return filtered;
    });
  };

  const handleAddToCart = () => {
    setCart(selectedProducts); // Store selected products
    setSpecialInst(specialInstructions); // Store special instructions
    console.log(specialInstructions);
    navigate('/client-home/cart'); // Navigate to cart
  };

  const toggleInstructions = (drinkName) => {
    setShowInstructions((prev) => ({
      ...prev,
      [drinkName]: !prev[drinkName],
    }));
  };

  const handleInstructionsChange = (e, drinkName) => {
    const value = e.target.value;
    setSpecialInstructions((prev) => ({
      ...prev,
      [drinkName]: value || '',
    }));
  };

  const handleSubmitInstructions = (drinkName) => {
    console.log(`Special instructions for ${drinkName}: ${specialInstructions[drinkName] || ''}`);
    setShowInstructions((prev) => ({
      ...prev,
      [drinkName]: false, // Hide the textarea after submitting
    }));
  };

  return (
      <div>
        {/* Store Banner Section */}
        <div className="relative">
          <img src={storePic} alt="Store Banner" className="w-full h-96 object-cover rounded-2xl" />
          <div className="absolute bottom-4 left-4 text-white">
            <h1 className="text-3xl pb-6 sm:pb-0 sm:text-7xl md:text-8xl font-bold ">{store}</h1>
          </div>

          {/* Search bar */}
          <div className="absolute bottom-4 right-4 flex items-center bg-white p-1 rounded-md border border-gray-300 ml-4">
            <FontAwesomeIcon icon={faSearch} className="text-gray-400 mr-2" />
            <input
                type="text"
                placeholder="Search for Drinks"
                value={drinkSearchTerm}
                onChange={(e) => setDrinkSearchTerm(e.target.value)}
                className="p-0 md:p-2 bg-transparent rounded-md focus:outline-none h-4 w-full"
            />
          </div>
        </div>

        {/* Products Section */}
        <div className="p-6 bg-white shadow-md rounded-lg mt-6 container mx-auto">

          {/* Promoted Items Section */}
          {promotedDrinks.length > 0 && (
              <div>
                <h2 className="text-2xl font-bold mb-4">🟢 Save on selected drinks</h2>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
                  {promotedDrinks.map((drink, index) => {
                    const discountedPrice = applyPromotion(drink.name, drink.price);
                    return (
                        <div key={index} className="bg-gray-50 border border-gray-200 rounded-lg overflow-hidden shadow-lg">
                          <img src={drinkPic} alt={drink.name} className="w-full h-32 object-cover" />
                          <div className="p-4">
                            <h3 className="text-xl font-semibold mb-2">{drink.name}</h3>
                            <div className="text-gray-700 mb-2">
                              <span>Price: </span>
                              <span className="line-through mr-2">R {drink.price}</span>
                              <span className="text-green-500">R {discountedPrice}</span>
                            </div>
                            <p className="text-gray-500 mb-2">Drink description</p>
                            <div className="flex flex-col mt-2">
                              <label className="text-sm font-medium mb-1">Quantity:</label>
                              <input
                                  type="number"
                                  min="0"
                                  className="border border-gray-300 rounded-md p-1 w-16"
                                  onChange={(e) => handleQuantityChange(drink.name, drink.price, e)}
                              />
                            </div>

                            {/* Special Instructions */}
                            <div className="mt-4">
                              <button
                                  className="text-gray-800 hover:underline"
                                  onClick={() => toggleInstructions(drink.name)}
                              >
                                {showInstructions[drink.name] ? 'Hide' : 'Add'} Special Instructions
                              </button>

                              {showInstructions[drink.name] && (
                                  <div className="mt-2">
                                                        <textarea
                                                            className="w-full p-2 border border-gray-300 rounded-md"
                                                            placeholder="Enter special instructions"
                                                            value={specialInstructions[drink.name] || ''}
                                                            onChange={(e) => handleInstructionsChange(e, drink.name)}
                                                        />
                                    <button
                                        className="mt-2 px-4 py-2 bg-black text-white font-semibold rounded-md hover:bg-gray-600"
                                        onClick={() => handleSubmitInstructions(drink.name)}
                                    >
                                      Submit Instructions
                                    </button>
                                  </div>
                              )}

                              {/* Display the submitted special instruction */}
                              {specialInstructions[drink.name] && !showInstructions[drink.name] && (
                                  <div className="mt-2 text-gray-600">
                                    Special Instructions: {specialInstructions[drink.name]}
                                  </div>
                              )}
                            </div>
                          </div>
                        </div>
                    );
                  })}
                </div>
              </div>
          )}

          {/* Regular Items Section */}
          {regularDrinks.length > 0 && (
              <div>
                <h2 className="text-2xl font-bold mb-4">All Drinks</h2>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
                  {regularDrinks.map((drink, index) => (
                      <div key={index} className="bg-gray-50 border border-gray-200 rounded-lg overflow-hidden shadow-lg">
                        <img src={drinkPic} alt={drink.name} className="w-full h-32 object-cover" />
                        <div className="p-4">
                          <h3 className="text-xl font-semibold mb-2">{drink.name}</h3>
                          <p className="text-gray-700 mb-2">Price: R {drink.price}</p>
                          <p className="text-gray-500 mb-2">Drink description</p>
                          <div className="flex flex-col mt-2">
                            <label className="text-sm font-medium mb-1">Quantity:</label>
                            <input
                                type="number"
                                min="0"
                                className="border border-gray-300 rounded-md p-1 w-16"
                                onChange={(e) => handleQuantityChange(drink.name, drink.price, e)}
                            />
                          </div>

                          {/* Special Instructions */}
                          <div className="mt-4">
                            <button
                                className="text-gray-800 hover:underline"
                                onClick={() => toggleInstructions(drink.name)}
                            >
                              {showInstructions[drink.name] ? 'Hide' : 'Add'} Special Instructions
                            </button>

                            {showInstructions[drink.name] && (
                                <div className="mt-2">
                                                    <textarea
                                                        className="w-full p-2 border border-gray-300 rounded-md"
                                                        placeholder="Enter special instructions"
                                                        value={specialInstructions[drink.name] || ''}
                                                        onChange={(e) => handleInstructionsChange(e, drink.name)}
                                                    />
                                  <button
                                      className="mt-2 px-4 py-2 bg-black text-white font-semibold rounded-md hover:bg-gray-600"
                                      onClick={() => handleSubmitInstructions(drink.name)}
                                  >
                                    Submit Instructions
                                  </button>
                                </div>
                            )}

                            {/* Display the submitted special instruction */}
                            {specialInstructions[drink.name] && !showInstructions[drink.name] && (
                                <div className="mt-2 text-gray-600">
                                  Special Instructions: {specialInstructions[drink.name]}
                                </div>
                            )}
                          </div>
                        </div>
                      </div>
                  ))}
                </div>
              </div>
          )}

          <div className="mt-6">
            <button
                onClick={handleAddToCart}
                className="px-4 py-2 bg-black text-white font-semibold rounded-md hover:bg-gray-600"
                disabled={filteredDrinks.length === 0}
            >
              Add to Cart
            </button>
          </div>
        </div>
      </div>
  );
}

export default Products;
